package com.finalanswer.server.rooms;

import java.util.*;
import com.erni.finalanswer.gameplay.lastcommand.CommandText;

/** Independent, authoritative command terminals. Public payloads contain controls, never solutions. */
final class CommandRace {
    enum Category { LOGIC, MECHANICAL, MEMORY, REACTION }
    static final Map<Category,Integer> DEFAULT_WEIGHTS=Map.of(Category.LOGIC,20,Category.MECHANICAL,50,Category.MEMORY,20,Category.REACTION,10);
    static final Map<Category,List<String>> FAMILIES=Map.of(
        Category.LOGIC,List.of("MATH","NUMBER_SEQUENCE","COMPARISON","FORBIDDEN","ODD_SYMBOL","DECIPHER","POSITION"),
        Category.MECHANICAL,List.of("BUTTON","CIRCUIT","LEVER_SEQUENCE","PRESSURE","RADIO","FAULTY_GAUGE","BALANCE","LEVER","ADJUSTER","HATCH","COLOR","ENTER_CODE","ANIMAL","SYMBOL"),
        Category.MEMORY,List.of("REVERSE","SHUTDOWN","NUMBER_MEMORY","ANIMAL_MEMORY","LIGHT_MEMORY","FIND_CHANGE"),
        Category.REACTION,List.of("TIMING","SILENCE","FALSE_COMMAND","DELAYED_EXECUTION"));
    static final class Player {
        int score,serial,sequence,failures; long readyAt,nextAt,revealUntil;String feedback="",family="",category="",input="";
        String previewFamily="";String instanceId=UUID.randomUUID().toString();boolean foundNote;boolean ready=true;boolean hidden;boolean online=true;long disconnectedAt;String clockNonce=UUID.randomUUID().toString().replace("-","");long clockSent=-1;int rtt;boolean clockConfirmed;boolean revealed;long taskSeed;Task task;final Deque<String> recent=new ArrayDeque<>();Memory memory;
        final Map<String,Object> mechanisms=new HashMap<>(Map.of("lever","UP","adjuster",0,"hatch",false,"light","OFF","code","0000","animal","CAT","symbol","SUN"));
        final LinkedHashSet<String> requests=new LinkedHashSet<>();
    }
    record Memory(String kind,List<String> values,int due) {}
    static final class Task {
        String instruction,kind="choice",answer=""; List<String> options=new ArrayList<>(),steps=new ArrayList<>();
        Map<String,Object> display=new LinkedHashMap<>();int[] cells;double pressure=30,velocity;double frequency=90;long lastTime;
        int target,low,high,estimatedMillis;boolean reverse;
    }
    private final long generationSalt=new java.security.SecureRandom().nextLong();
    final int difficulty=Math.max(1,Math.min(3,Integer.getInteger("lc.difficulty",2)));
    boolean requireReady,barrierOpen;long raceTime;final long seed;final long startedAt;final Map<String,Player> players=new LinkedHashMap<>();
    record Telemetry(long completions,long totalMillis){Telemetry add(long duration){return new Telemetry(completions+1,totalMillis+duration);}}
    final Map<String,Telemetry> telemetry=new LinkedHashMap<>();
    final Map<Category,Integer> weights;String winner="";long finishedAt;boolean started;
    CommandRace(long seed,long now){this(seed,now,configuredWeights());}
    CommandRace(long seed,long now,boolean requireReady){this(seed,now);this.requireReady=requireReady;}
    CommandRace(long seed,long now,Map<Category,Integer> weights){this.seed=seed;startedAt=now;raceTime=now;this.weights=Map.copyOf(weights);if(weights.values().stream().anyMatch(x->x<0)||weights.values().stream().mapToLong(x->x).sum()<1||weights.values().stream().mapToLong(x->x).sum()>1000000)throw new IllegalArgumentException("weights");}
    static Map<Category,Integer> configuredWeights(){var result=new EnumMap<Category,Integer>(Category.class);for(var c:Category.values())result.put(c,Integer.getInteger("lc.weight."+c.name().toLowerCase(Locale.ROOT),DEFAULT_WEIGHTS.get(c)));return result;}
    void start(long now){started=true;for(var e:players.entrySet())next(e.getKey(),e.getValue(),now);tryOpen(now);}
    void tryOpen(long now){if(requireReady&&!barrierOpen&&started&&!players.isEmpty()&&players.values().stream().allMatch(p->p.ready&&!p.hidden)){barrierOpen=true;raceTime=now;for(Player p:players.values())resume(p,now);}}
    Player player(String id,long now){return players.computeIfAbsent(id,key->{var p=new Player();if(requireReady){p.ready=false;p.online=false;p.disconnectedAt=now;}if(started)next(key,p,now);return p;});}
    void disconnect(String id,long now){Player p=players.get(id);if(p==null)return;p.hidden=false;if(requireReady)p.ready=false;if(!p.online)return;p.online=false;p.disconnectedAt=now;p.clockConfirmed=false;p.clockNonce=UUID.randomUUID().toString().replace("-","");p.clockSent=-1;p.rtt=0;}
    void resume(Player p,long now){if(p.online||!p.ready||requireReady&&!barrierOpen)return;long paused=Math.max(0,now-p.disconnectedAt);p.online=true;p.clockConfirmed=false;p.clockNonce=UUID.randomUUID().toString().replace("-","");p.clockSent=-1;p.rtt=0;if(p.readyAt>0)p.readyAt+=paused;if(p.nextAt>0)p.nextAt+=paused;if(p.revealUntil>0)p.revealUntil+=paused;if(p.task!=null){p.task.lastTime=now;for(String key:List.of("memorizeUntil","signalEndsAt"))if(p.task.display.containsKey(key))p.task.display.put(key,((Number)p.task.display.get(key)).longValue()+paused);}}
    static int n(Random r,int min,int max){return min+r.nextInt(max-min+1);}
    static <T> T pick(Random r,List<T> xs){return xs.get(r.nextInt(xs.size()));}
    String family(Player p){var r=new Random(seed+104729L*p.serial);int total=weights.values().stream().mapToInt(x->x).sum(),ticket=r.nextInt(total);Category c=Category.LOGIC;for(Category x:Category.values()){ticket-=weights.getOrDefault(x,0);if(ticket<0){c=x;break;}}var pool=new ArrayList<>(FAMILIES.get(c));pool.removeAll(p.recent);if(pool.isEmpty())pool.addAll(FAMILIES.get(c));p.category=c.name();if(c==Category.MECHANICAL){var weighted=new ArrayList<String>();for(String type:pool)for(int i=0,count=Set.of("BUTTON","HATCH","ANIMAL","SYMBOL","LEVER","LEVER_SEQUENCE","ENTER_CODE").contains(type)?4:1;i<count;i++)weighted.add(type);return pick(r,weighted);}return pick(r,pool);}
    void next(String id,Player p,long now){p.serial++;String failedFamily=p.feedback.equals("WRONG COMMAND")?p.family:"";p.family=!p.previewFamily.isEmpty()?p.previewFamily:failedFamily.isEmpty()?family(p):failedFamily;if(p.family.equals("NUMBER_MEMORY")&&(p.memory!=null||p.score>=17)){p.family="MATH";p.category="LOGIC";}if(p.memory!=null&&p.score>=p.memory.due){p.family="RECALL";p.category="MEMORY";}
        if(p.family.equals("RECALL")&&p.memory==null){p.family="NUMBER_MEMORY";}p.instanceId=UUID.randomUUID().toString();p.taskSeed=(seed+104729L*p.serial+Integer.toUnsignedLong(id.hashCode())*31)^generationSalt;p.foundNote=false;p.sequence=0;p.input="";p.feedback="";p.nextAt=0;p.readyAt=now+220;p.revealUntil=0;p.revealed=false;
        for(int attempt=0;attempt<8;attempt++){try{p.task=generate(p.family,new Random(p.taskSeed+attempt*7919L),p,now);validateGenerated(p.task);break;}catch(IllegalStateException invalid){if(attempt==7)throw invalid;}}p.recent.addLast(p.family);while(p.recent.size()>4)p.recent.removeFirst();
    }
    void preview(String id,String family,long now){if(!FAMILIES.values().stream().anyMatch(xs->xs.contains(family))&&!family.equals("RECALL"))throw new RoomService.Failure(400,"INVALID_TASK_FAMILY");Player p=player(id,now);p.previewFamily=family;p.category=FAMILIES.entrySet().stream().filter(e->e.getValue().contains(family)).map(e->e.getKey().name()).findFirst().orElse("MEMORY");p.score=0;p.failures=0;p.memory=null;p.feedback="";winner="";finishedAt=0;if(!started)start(now);else next(id,p,now);}
    static final List<String> COLORS=List.of("RED","GREEN","BLUE","YELLOW"),SYMBOLS=List.of("☀","☾","★","◆"),ANIMALS=List.of("CAT","OWL","WOLF","DEER");
    Task generate(String family,Random r,Player p,long now){Task t=new Task();t.lastTime=now;
        switch(family){
            case "MATH"->{int a=n(r,2,10+difficulty*5),b=n(r,2,3+difficulty*3),c=n(r,2,3+difficulty*3);t.kind="number";int mode=r.nextInt(5);t.instruction=switch(mode){case 0->a+" + "+b+" × "+c+" = ?";case 1->"("+a+" − "+b+") × "+c+" = ?";case 2->(a*b)+" ÷ "+b+" − "+c+" = ?";case 3->a+" − "+b+" × "+c+" = ?";default->"("+a+" + "+b+") ÷ "+(a+b)+" + "+c+" = ?";};t.answer=""+switch(mode){case 0->a+b*c;case 1->(a-b)*c;case 2->a-c;case 3->a-b*c;default->1+c;};}
            case "NUMBER_SEQUENCE"->{t.kind="number";int a=n(r,1,8),d=n(r,2,5),mode=r.nextInt(6);List<Integer> values=new ArrayList<>();for(int i=0;i<5;i++)values.add(switch(mode){case 0->a+i*d;case 1->a*(int)Math.pow(2,i);case 2->a+d*i*(i+1)/2;case 3->a+(i/2)*d+(i%2==0?0:20);case 4->a*(int)Math.pow(3,i);default->(a+d)*(int)Math.pow(2,i)-d;});t.answer=""+values.remove(4);t.instruction=values+", ? / RULE: "+List.of("constant difference","multiply by 2","differences increase by "+d,"two alternating +"+d+" series","multiply by 3","multiply by 2 then add "+d).get(mode);}
            case "COMPARISON"->{int mode=r.nextInt(5),target=n(r,20,40);t.instruction=List.of("SELECT LARGEST","SELECT SMALLEST","CLOSEST TO "+target,"EQUAL TO "+target,"GREATEST ABSOLUTE DIFFERENCE").get(mode);int best=0;double bestValue=-1e9;List<Integer> candidates=new ArrayList<>();for(int value=2;value<=70;value++)candidates.add(value);Collections.shuffle(candidates,r);for(int i=0;i<4;i++){int value=candidates.get(i);if(mode==3&&i==0)value=target;int b=n(r,1,12);t.options.add(mode==4?(value+b)+" − "+b:(value-b)+" + "+b);double rank=switch(mode){case 1->-value;case 2->-Math.abs(value-target);case 3->value==target?100:0;default->value;};if(rank>bestValue){best=i;bestValue=rank;}}if(mode==2){t.options.clear();for(int i=0;i<4;i++)t.options.add((target+2+i*3)+" − 0");best=0;}if(mode==3){for(int i=1;i<4;i++)t.options.set(i,(target+i)+" + 1");best=0;}String correct=t.options.get(best);Collections.shuffle(t.options,r);t.answer=""+t.options.indexOf(correct);}
            case "FORBIDDEN"->{t.options=new ArrayList<>(COLORS);int forbidden=r.nextInt(4);t.instruction="PRESS ANY COLOR EXCEPT "+COLORS.get(forbidden);t.answer="except:"+forbidden;t.display.put("spatialOnly",true);}
            case "CONDITIONAL"->{boolean a=r.nextBoolean(),b=r.nextBoolean();int mode=r.nextInt(4);boolean result=switch(mode){case 0->a;case 1->a&&b;case 2->a||b;default->!a;};boolean switches=r.nextBoolean();t.display.put("inputsKind",switches?"SWITCHES":"LAMPS");t.display.put("lamps",List.of(a,b));t.instruction=(switches?"SWITCHES: ":"LAMPS: ")+"A="+(a?"ON":"OFF")+", B="+(b?"ON":"OFF")+". IF "+List.of("A","A AND B","A OR B","NOT A").get(mode)+": BLUE; ELSE: YELLOW";t.options=new ArrayList<>(COLORS);t.answer=result?"2":"3";}
            case "STROOP"->{int word=r.nextInt(4),ink=(word+n(r,1,3))%4;int mode=r.nextInt(4);t.instruction=List.of("SELECT WRITTEN COLOR","SELECT INK COLOR (ACCESSIBLE LABEL BELOW)","PRESS THE BUTTON MATCHING THE INK","SELECT A COLOR THAT DOES NOT MATCH THE INK").get(mode);t.display.put("word",COLORS.get(word));t.display.put("ink",COLORS.get(ink));t.options=new ArrayList<>(COLORS);t.answer=mode==3?"except:"+ink:""+(mode==0?word:ink);}
            case "ODD_SYMBOL"->{int odd=r.nextInt(6);List<String> pool=pick(r,List.of(SYMBOLS,List.of("↑","→","↓","←"),List.of("△","□","⬟","⬡"),List.of("◀","▶","▲","▼")));String normal=pick(r,pool),other=pick(r,pool.stream().filter(s->!s.equals(normal)).toList());for(int i=0;i<6;i++)t.options.add(i==odd?other:normal);t.instruction="SELECT THE ONLY DIFFERENT SYMBOL";t.answer=""+odd;}
            case "DECIPHER"->{t.kind="number";var digits=new ArrayList<>(List.of(1,2,3,4,5,6,7,8,9));Collections.shuffle(digits,r);StringBuilder mapping=new StringBuilder(),code=new StringBuilder(),answer=new StringBuilder();for(int i=0;i<4;i++)mapping.append(SYMBOLS.get(i)).append('=').append(digits.get(i)).append("  ");for(int i=0;i<3;i++){int k=r.nextInt(4);code.append(SYMBOLS.get(k)).append(' ');answer.append(digits.get(k));}t.instruction=mapping+" / DECODE: "+code;t.answer=answer.toString();}
            case "POSITION"->{for(String color:COLORS)for(String symbol:SYMBOLS)t.options.add(color+" "+symbol);Collections.shuffle(t.options,r);t.options=new ArrayList<>(t.options.subList(0,9));int index=r.nextInt(9),row=index/3,col=index%3,mode=r.nextInt(9);t.instruction=switch(mode){case 0->"SELECT ROW "+(row+1)+", COLUMN "+(col+1)+" (TOP TO BOTTOM, LEFT TO RIGHT)";case 1->"SELECT #"+(col+1)+" FROM LEFT IN ROW "+(row+1);case 2->"SELECT #"+(3-col)+" FROM RIGHT IN ROW "+(row+1);case 3->"SELECT #"+(row+1)+" FROM TOP IN COLUMN "+(col+1);case 4->"SELECT #"+(3-row)+" FROM BOTTOM IN COLUMN "+(col+1);case 5->{index=4;yield "SELECT CENTER CELL";}case 7->"SELECT THE "+t.options.get(index)+" TILE";case 8->{int anchor=1+3*r.nextInt(3);index=anchor-1;yield "SELECT TILE IMMEDIATELY LEFT OF "+t.options.get(anchor);}default->{index=pick(r,List.of(1,3,5,7));yield "SELECT CELL IMMEDIATELY "+Map.of(1,"ABOVE",3,"LEFT OF",5,"RIGHT OF",7,"BELOW").get(index)+" CENTER";}};t.answer=""+index;}
            case "CIRCUIT"->{t.kind="circuit";t.instruction="CONNECT LEFT SOURCE TO RIGHT OUTPUT / TAP TO ROTATE; CONFIRM";t.cells=switch((int)Math.floorMod(seed+p.serial,3)){case 0->new int[]{12,0,6,3,10,9,0,0,0};case 1->new int[]{12,6,10,3,9,0,0,0,0};default->new int[]{10,12,6,0,3,9,0,0,0};};if(r.nextBoolean())t.cells[4]|=4;Random turns=new Random(seed+49999L*p.serial);for(int i=0;i<9;i++)for(int j=0,count=1+turns.nextInt(3);j<count;j++)t.cells[i]=rotate(t.cells[i]);t.display.put("board",Arrays.stream(t.cells).boxed().toList());}
            case "LEVER_SEQUENCE","SHUTDOWN"->{t.kind="sequence";String lever=pick(r,List.of("UP","MIDDLE","DOWN"));int angle=r.nextInt(4)*45;t.steps=new ArrayList<>(List.of("LEVER_MODULE:"+lever,"ADJUSTER:"+angle));Collections.shuffle(t.steps,r);t.steps.add("BIG_BUTTON:PRESS");p.mechanisms.put("lever",List.of("UP","MIDDLE","DOWN").get((List.of("UP","MIDDLE","DOWN").indexOf(lever)+2)%3));p.mechanisms.put("adjuster",Math.floorMod(angle-45,180));t.instruction=String.join(" → ",t.steps);t.display.put("mechanical",true);if(family.equals("SHUTDOWN")){p.revealUntil=now+4400;t.display.put("memorizeUntil",p.revealUntil);}}
            case "BROKEN_SWITCH"->{int bad=r.nextInt(4);t.kind="switches";t.target=bad;t.low=r.nextInt(4);t.display.put("tileHints",List.of("RESET","RESET","RESET","RESET"));t.instruction="TEST SWITCHES: GOOD SWITCH STAYS SET AND LIGHTS ITS OWN LAMP. SELECT FAULTY SWITCH / CONFIRM";t.options=List.of("A","B","C","D");t.answer=""+bad;t.display.put("lamps",List.of(false,false,false,false));}
            case "PRESSURE"->{t.kind="pressure";t.low=n(r,20,72);t.high=t.low+14-2*difficulty;t.pressure=Math.max(0,Math.min(100,(t.low+t.high)/2.+(r.nextBoolean()?20:-20)));int mode=r.nextInt(4);String unit=List.of("PSI","бар","мА","°C").get(mode),quantity=List.of("ДАВЛЕНИЕ","ДАВЛЕНИЕ","ТОК","ТЕМПЕРАТУРУ").get(mode);double scale=mode==1?.1:mode==2?.16:1,offset=mode==2?4:0;int decimals=mode==1||mode==2?1:0;t.display.put("unit",unit);t.display.put("scale",scale);t.display.put("offset",offset);t.display.put("decimals",decimals);t.instruction="УСТАНОВИТЕ "+quantity+" "+String.format(Locale.ROOT,"%."+decimals+"f–%."+decimals+"f",t.low*scale+offset,t.high*scale+offset)+" "+unit+" / ПОДТВЕРДИТЕ КРАСНОЙ КНОПКОЙ";t.display.put("range",List.of(t.low,t.high));}
            case "FUSE"->{int load=n(r,7,24);t.options=List.of("5 A","10 A","15 A","20 A","25 A","30 A");t.instruction="SMALLEST FUSE RATED AT LEAST "+load+" A";t.answer=""+((load+4)/5-1);}
            case "RADIO"->{t.kind="radio";t.target=n(r,920,1040);t.frequency=t.target/10.+(r.nextBoolean()?1:-1)*(2+.5*Math.floorMod(seed+p.serial,3));t.instruction="TUNE TO "+(t.target/10.0)+" MHz ± 0.3 / CONFIRM";}
            case "FAULTY_GAUGE"->{int reference=n(r,10,30),bad=r.nextInt(4);t.instruction="RULE: EVERY GAUGE = "+reference+" × 2. SELECT FAULTY GAUGE";for(int i=0;i<4;i++)t.options.add("GAUGE "+(i+1)+": "+(2*reference+(i==bad?n(r,2,8):0)));t.answer=""+bad;}
            case "BALANCE"->{t.kind="balance";t.target=n(r,5,12);t.pressure=t.target+(r.nextBoolean()?3:-3);t.display.put("target",t.target);t.instruction="BALANCE TARGET "+t.target+" kg / ADD OR REMOVE 1, 2, 5 kg; CONFIRM";}
            case "REVERSE","LIGHT_MEMORY","SYMBOL_MEMORY","ANIMAL_MEMORY"->{t.kind="sequence";List<String> pool=family.equals("ANIMAL_MEMORY")?ANIMALS:family.equals("LIGHT_MEMORY")?COLORS:SYMBOLS;t.options=new ArrayList<>(pool);for(int i=0,length=Math.max(2,Math.min(4,Integer.getInteger("lc.memory.length",2+(int)Math.floorMod(seed+p.serial,3))));i<length;i++)t.steps.add(""+r.nextInt(4));t.reverse=family.equals("REVERSE");t.instruction=(t.reverse?"MEMORIZE / REPEAT IN REVERSE: ":"MEMORIZE / REPEAT: ")+String.join(" → ",t.steps.stream().map(x->pool.get(Integer.parseInt(x))).toList());p.revealUntil=now+4400;t.display.put("memorizeUntil",p.revealUntil);if(t.reverse)Collections.reverse(t.steps);}
            case "NUMBER_MEMORY"->{t.kind="store";String kind=pick(r,List.of("NUMBER","ANIMAL","SYMBOL","COLOR","SWITCH","SEQUENCE","LIGHT_SEQUENCE"));List<String> values=switch(kind){case "ANIMAL"->List.of(pick(r,ANIMALS));case "SYMBOL"->List.of(pick(r,SYMBOLS));case "COLOR"->List.of(pick(r,COLORS));case "SWITCH"->List.of(pick(r,List.of("UP","MIDDLE","DOWN")));case "SEQUENCE"->List.of(pick(r,SYMBOLS),pick(r,SYMBOLS),pick(r,SYMBOLS));case "LIGHT_SEQUENCE"->List.of(pick(r,COLORS),pick(r,COLORS),pick(r,COLORS));default->List.of(""+n(r,1000,9999));};p.memory=new Memory(kind,values,p.score+3);if(kind.equals("LIGHT_SEQUENCE"))t.display.put("flashes",values.stream().map(x->""+COLORS.indexOf(x)).toList());t.instruction="REMEMBER "+kind+": "+String.join(" → ",values)+" / RECALL AFTER 3 CORRECT TASKS";p.revealUntil=now+4400;}
            case "RECALL"->{String kind=p.memory.kind,stored=p.memory.values.get(0);if(kind.equals("LIGHT_SEQUENCE")){t.kind="sequence";t.options=new ArrayList<>(COLORS);t.steps=new ArrayList<>(p.memory.values.stream().map(x->""+COLORS.indexOf(x)).toList());t.instruction="REPEAT THE STORED LIGHT SEQUENCE";}else if(kind.equals("NUMBER")){t.kind="number";int mode=r.nextInt(6);t.instruction="STORED NUMBER: ENTER "+List.of("FIRST DIGIT","LAST DIGIT","FIRST TWO DIGITS","LAST TWO DIGITS","SECOND DIGIT","FULL NUMBER").get(mode);t.answer=switch(mode){case 0->stored.substring(0,1);case 1->stored.substring(3);case 2->stored.substring(0,2);case 3->stored.substring(2);case 4->stored.substring(1,2);default->stored;};}else{List<String> pool=switch(kind){case "ANIMAL"->ANIMALS;case "COLOR"->COLORS;case "SWITCH"->List.of("UP","MIDDLE","DOWN");default->SYMBOLS;};t.options=new ArrayList<>(pool);Collections.shuffle(t.options,r);int position=kind.equals("SEQUENCE")?r.nextInt(p.memory.values.size()):0;t.instruction="SELECT STORED "+kind+(kind.equals("SEQUENCE")?" AT POSITION "+(position+1):"");t.answer=""+t.options.indexOf(p.memory.values.get(position));}}
            case "FIND_CHANGE"->{int bad=r.nextInt(4);int mode=r.nextInt(5);List<String> pool=List.of(SYMBOLS,COLORS,List.of("UP","DOWN"),List.of("10 PSI","20 PSI","30 PSI","40 PSI"),List.of("ON","OFF")).get(mode);for(int i=0;i<4;i++)t.options.add(pick(r,pool));t.instruction="MEMORIZE THE "+List.of("SYMBOL","LAMP COLOR","SWITCH","GAUGE","ILLUMINATION").get(mode)+" PANEL";t.display.put("afterInstruction","SELECT THE CHANGED POSITION");t.answer=""+bad;p.revealUntil=now+4400;t.display.put("memorizeUntil",p.revealUntil);t.display.put("original",List.copyOf(t.options));t.options.set(bad,pool.get((pool.indexOf(t.options.get(bad))+1)%pool.size()));}
            case "TIMING"->{t.kind="timing";t.low=n(r,20,65);t.high=t.low+20+(int)Math.floorMod(seed+p.serial,3)*5-5*(difficulty-2);t.instruction="PRESS IN TARGET SECTOR "+t.low+"–"+t.high;t.display.put("range",List.of(t.low,t.high));int direction=r.nextBoolean()?1:-1;t.display.put("period",3200+800*(int)Math.floorMod(seed+p.serial,3));t.display.put("direction",direction);t.display.put("start",Math.floorMod((t.low+t.high)/2-direction*50,100));}
            case "SILENCE"->{t.kind="silence";t.target=n(r,2800,3800)+500*(difficulty-2);t.instruction="WAIT FOR SILENCE / GREEN STATUS, THEN CONFIRM";t.display.put("signalEndsAt",p.readyAt+t.target);}
            case "FALSE_COMMAND"->{int display=r.nextInt(4),spoken=(display+1)%4;boolean audio=r.nextBoolean();t.instruction="TRUST "+(audio?"AUDIO (CAPTION)":"DISPLAY")+" / DISPLAY: PRESS "+COLORS.get(display)+" / AUDIO CAPTION: PRESS "+COLORS.get(spoken);t.options=new ArrayList<>(COLORS);t.display.put("spoken","PRESS "+COLORS.get(spoken));t.display.put("spokenColor",COLORS.get(spoken));t.answer=""+(audio?spoken:display);}
            case "DELAYED_EXECUTION"->{t.kind="delayed";t.instruction="CONFIRM AFTER SECOND SIGNAL, BEFORE THIRD (ONE SIGNAL EACH SECOND)";t.display.put("interval",1000);}
            case "LEVER"->{t.kind="physical";t.answer=pick(r,List.of("UP","MIDDLE","DOWN"));t.instruction="SET LEVER "+t.answer+" / RED BUTTON CONFIRMS";}
            case "ADJUSTER"->{t.kind="physical";t.answer=""+(r.nextInt(4)*45);t.instruction="SET ADJUSTER "+t.answer+"° / RED BUTTON CONFIRMS";}
            case "ANIMAL","SYMBOL"->{t.kind="physical";t.answer=pick(r,family.equals("ANIMAL")?ANIMALS:List.of("SUN","MOON","STAR","KEY"));t.options=new ArrayList<>(family.equals("ANIMAL")?ANIMALS:List.of("SUN","MOON","STAR","KEY"));t.display.put("physicalSelector",true);t.display.put("spatialOnly",true);t.instruction="SELECT "+family+": "+t.answer+" / RED BUTTON CONFIRMS";}
            case "COLOR"->{t.kind="physical";t.answer=pick(r,COLORS);t.instruction="SELECT LAMP "+t.answer+" / RED BUTTON CONFIRMS";}
            case "BUTTON"->{t.options=new ArrayList<>(COLORS);t.answer=""+r.nextInt(4);t.instruction="PRESS THE "+COLORS.get(Integer.parseInt(t.answer))+" PHYSICAL BUTTON";t.display.put("spatialOnly",true);}
            case "HATCH"->{t.kind="physical";t.instruction="FIND THE NOTE INSIDE THE HATCH / ENTER ITS CODE / RED BUTTON CONFIRMS";t.answer=String.format(Locale.ROOT,"%04d",r.nextInt(10000));p.mechanisms.put("hatch",false);}
            case "ENTER_CODE"->{t.kind="physical";t.answer=String.format(Locale.ROOT,"%04d",r.nextInt(10000));t.instruction="ENTER CODE "+t.answer+" / RED BUTTON CONFIRMS";}
            default->throw new IllegalArgumentException("Unknown family "+family);
        }
        if(family.equals("LIGHT_MEMORY")){t.display.put("flashes",List.copyOf(t.steps));t.instruction="MEMORIZE THE LIGHTS";boolean reverse=Math.floorMod(seed+p.serial,2)==0;t.display.put("afterInstruction",reverse?"REPEAT THE LIGHTS IN REVERSE":"REPEAT THE LIGHT SEQUENCE");if(reverse)Collections.reverse(t.steps);p.revealUntil=now+4400;}
        if(family.equals("SYMBOL_MEMORY")||family.equals("ANIMAL_MEMORY")){List<String> pool=family.equals("ANIMAL_MEMORY")?ANIMALS:SYMBOLS;var shuffled=new ArrayList<>(pool);Collections.shuffle(shuffled,r);List<String> prompt=new ArrayList<>(shuffled.subList(0,3));int mode=r.nextInt(3),position=r.nextInt(3);String answer;
            if(mode==0){answer=prompt.get(position);t.display.put("afterInstruction","WHICH "+(family.equals("ANIMAL_MEMORY")?"ANIMAL":"SYMBOL")+" WAS AT POSITION "+(position+1)+"?");}
            else if(mode==1){prompt.add(1,prompt.get(1));answer=prompt.get(1);t.display.put("afterInstruction","WHICH ITEM APPEARED TWICE?");}
            else{answer=shuffled.get(3);t.display.put("afterInstruction","WHICH ITEM WAS MISSING?");}
            t.kind="choice";t.options=new ArrayList<>(pool);Collections.shuffle(t.options,r);t.answer=""+t.options.indexOf(answer);t.steps.clear();t.instruction="MEMORIZE: "+String.join(" → ",prompt);p.revealUntil=now+4400;t.display.put("memorizeUntil",p.revealUntil);
        }
        if(family.equals("ANIMAL_MEMORY")&&r.nextBoolean()){var symbols=new ArrayList<>(SYMBOLS);Collections.shuffle(symbols,r);int target=r.nextInt(4);StringBuilder mapping=new StringBuilder("MEMORIZE PAIRS: ");for(int i=0;i<4;i++)mapping.append(ANIMALS.get(i)).append('=').append(symbols.get(i)).append("  ");t.instruction=mapping.toString();t.display.put("afterInstruction","SELECT THE ANIMAL PAIRED WITH "+symbols.get(target));t.answer=""+t.options.indexOf(ANIMALS.get(target));}
        switch(family){
            case "LEVER"->p.mechanisms.put("lever",List.of("UP","MIDDLE","DOWN").get((List.of("UP","MIDDLE","DOWN").indexOf(t.answer)+2)%3));
            case "ADJUSTER"->p.mechanisms.put("adjuster",Math.floorMod(Integer.parseInt(t.answer)-45,180));
            case "COLOR"->{var states=List.of("OFF","RED","GREEN","YELLOW","BLUE");p.mechanisms.put("light",states.get(states.indexOf(t.answer)-1));}
            case "ENTER_CODE","HATCH"->{StringBuilder initial=new StringBuilder();for(char digit:t.answer.toCharArray())initial.append((digit-'0'+(r.nextBoolean()?8:2))%10);p.mechanisms.put("code",initial.toString());}
            case "ANIMAL"->p.mechanisms.put("animal",ANIMALS.get((ANIMALS.indexOf(t.answer)+1)%4));
            case "SYMBOL"->{var symbols=List.of("SUN","MOON","STAR","KEY");p.mechanisms.put("symbol",symbols.get((symbols.indexOf(t.answer)+1)%4));}
            default->{}
        }
        if(Set.of("BUTTON","FORBIDDEN","FALSE_COMMAND","LIGHT_MEMORY","TIMING","SILENCE","DELAYED_EXECUTION","PRESSURE","RADIO","BALANCE").contains(family)||family.equals("RECALL")&&t.kind.equals("sequence"))t.display.put("spatialOnly",true);
        t.estimatedMillis=switch(t.kind){case "number"->6000;case "circuit"->6500;case "sequence"->t.display.containsKey("mechanical")?5000:7500;case "pressure"->5500;case "radio"->5000;case "balance"->4500;case "store"->4400;case "timing","silence","delayed"->5000;default->3500;};
        return t;
    }
    static void validateGenerated(Task t){
        if(t.instruction==null||t.instruction.isBlank())throw new IllegalStateException("instruction");
        if(t.kind.equals("choice")){if(t.options.size()<2)throw new IllegalStateException("choices");if(t.answer.startsWith("except:")){int forbidden;try{forbidden=Integer.parseInt(t.answer.substring(7));}catch(NumberFormatException error){throw new IllegalStateException("restriction",error);}if(forbidden<0||forbidden>=t.options.size())throw new IllegalStateException("restriction");}else try{int i=Integer.parseInt(t.answer);if(i<0||i>=t.options.size())throw new IllegalStateException("answer range");}catch(NumberFormatException error){throw new IllegalStateException("answer index",error);}}
        if(t.kind.equals("number")&&(t.answer.length()>9||!t.answer.matches("-?[0-9]{1,9}")))throw new IllegalStateException("numeric answer");
        if(t.kind.equals("pressure")&&(t.low<0||t.high>100||t.low>=t.high))throw new IllegalStateException("pressure range");
        if(t.kind.equals("radio")&&(t.target<880||t.target>1080))throw new IllegalStateException("radio range");
        if(t.kind.equals("sequence")){if(t.steps.isEmpty())throw new IllegalStateException("sequence");if(!t.display.containsKey("mechanical"))for(String step:t.steps)try{int index=Integer.parseInt(step);if(index<0||index>=t.options.size())throw new IllegalStateException("sequence index");}catch(NumberFormatException error){throw new IllegalStateException("sequence index",error);}}
        if(t.kind.equals("radio")&&(t.frequency<88||t.frequency>108))throw new IllegalStateException("radio initial state");
        if(t.kind.equals("balance")&&(t.target<0||t.target>100||t.pressure<0||t.pressure>100))throw new IllegalStateException("balance bounds");
        if(t.kind.equals("circuit")&&(t.cells==null||t.cells.length!=9||Arrays.stream(t.cells).anyMatch(mask->mask<0||mask>15)||!solvable(t.cells.clone(),0)))throw new IllegalStateException("unsolvable circuit");
    }
    static boolean solvable(int[] cells,int at){if(at==cells.length)return connected(cells);int original=cells[at],mask=original;do{cells[at]=mask;if(solvable(cells,at+1)){cells[at]=original;return true;}mask=rotate(mask);}while(mask!=original);cells[at]=original;return false;}
    static boolean connected(int[] cells){if(cells.length!=9||(cells[0]&8)==0)return false;boolean[] visited=new boolean[9];Deque<Integer> q=new ArrayDeque<>();q.add(0);visited[0]=true;int[] delta={-3,1,3,-1};for(;!q.isEmpty();){int i=q.remove();if(i==2&&(cells[i]&2)!=0)return true;for(int d=0;d<4;d++){int j=i+delta[d];if(j<0||j>=9||d==1&&i%3==2||d==3&&i%3==0||visited[j])continue;if((cells[i]&(1<<d))!=0&&(cells[j]&(1<<((d+2)%4)))!=0){visited[j]=true;q.add(j);}}}return false;}
    static int rotate(int mask){return ((mask<<1)&15)|(mask>>3);}
    boolean action(String id,String request,String taskId,String element,String action,String value,long now){if(value.length()>32||request.isBlank())return false;Player p=player(id,now);if(element.equals("TOUCH_PANEL")&&action.equals("CLIENT_READY")){if(!taskId.equals(taskId(p)))return false;if(p.ready)return false;p.ready=true;tryOpen(now);if(!p.hidden)resume(p,now);return true;}if(element.equals("TOUCH_PANEL")&&action.equals("VISIBILITY")){if(value.equals("HIDDEN")){disconnect(id,now);p.hidden=true;return true;}if(value.equals("VISIBLE")){p.hidden=false;tryOpen(now);resume(p,now);return true;}return false;}if(element.equals("TOUCH_PANEL")&&action.equals("CLOCK_SYNC")){if(!p.clockConfirmed&&p.clockSent>=0&&value.equals(p.clockNonce)){p.rtt=(int)Math.max(0,Math.min(250,now-p.clockSent));p.clockConfirmed=true;return true;}return false;}if(!p.online||!started||!winner.isEmpty()||p.task==null||!taskId.equals(taskId(p))||now<p.readyAt||p.nextAt>0||!p.requests.add(request))return false;while(p.requests.size()>2048)p.requests.remove(p.requests.iterator().next());Task t=p.task;boolean submit=false,correct=false;
        if(element.equals("BIG_BUTTON")&&action.equals("PRESS")&&Set.of("timing","silence","delayed").contains(t.kind))return action(id,request+":reaction",taskId,"TOUCH_PANEL","CONFIRM","",now);
        if((Set.of("BUTTON","LIGHT_MEMORY","FORBIDDEN","CONDITIONAL","STROOP","FALSE_COMMAND").contains(p.family)||p.family.equals("RECALL")&&t.kind.equals("sequence"))&&element.startsWith("SMALL_BUTTON_")&&action.equals("PRESS")){String number=element.substring(13);if(number.matches("[1-4]"))return action(id,request+":sequence",taskId,"TOUCH_PANEL","SELECT",""+(Integer.parseInt(number)-1),now);return false;}
        if(element.equals("TOUCH_PANEL")&&action.equals("RESTART_MEMORY")&&Set.of("RECALL","NUMBER_MEMORY").contains(p.family)&&p.memory!=null){Memory stored=p.memory;boolean recall=p.family.equals("RECALL");p.memory=new Memory(stored.kind,stored.values,p.score+(recall?0:3));p.instanceId=UUID.randomUUID().toString();p.family="NUMBER_MEMORY";p.category="MEMORY";p.sequence=0;p.input="";p.feedback="";p.nextAt=0;p.readyAt=now+220;p.revealUntil=now+4400;p.revealed=false;p.task=new Task();p.task.kind="store";p.task.instruction="REMEMBER "+stored.kind+": "+String.join(" → ",stored.values);p.task.display.put("memorizeUntil",p.revealUntil);if(stored.kind.equals("LIGHT_SEQUENCE"))p.task.display.put("flashes",stored.values.stream().map(x->""+COLORS.indexOf(x)).toList());p.task.estimatedMillis=4400;return true;}
        if(now<p.revealUntil)return false;
        if(element.equals("TOUCH_PANEL")){
            if(action.equals("SELECT_PHYSICAL")&&t.kind.equals("physical")&&Set.of("ANIMAL","SYMBOL").contains(p.family)&&t.options.contains(value)){p.mechanisms.put(p.family.equals("ANIMAL")?"animal":"symbol",value);}
            else if(action.equals("KEY")&&t.kind.equals("number")){if(value.equals("CLEAR"))p.input="";else if(value.equals("DELETE")){if(!p.input.isEmpty())p.input=p.input.substring(0,p.input.length()-1);}else if(value.matches("[0-9-]")&&p.input.length()<9&&( !value.equals("-")||p.input.isEmpty()))p.input+=value;else return false;}
            else if(action.equals("ROTATE")&&t.kind.equals("circuit")){int i=index(value,9);if(t.cells[i]==0)return false;t.cells[i]=rotate(t.cells[i]);}
            else if(action.equals("ADJUST")&&Set.of("pressure","radio","balance").contains(t.kind)){if(!Set.of("-5","-2","-1","1","2","5").contains(value))return false;int delta=Integer.parseInt(value);if(t.kind.equals("radio"))t.frequency=Math.max(88,Math.min(108,t.frequency+delta*.1));else if(t.kind.equals("pressure")){t.pressure=Math.max(0,Math.min(100,t.pressure+delta));t.velocity=Math.max(-12,Math.min(12,t.velocity+delta));}else t.pressure=Math.max(0,Math.min(100,t.pressure+delta));}
            else if(action.equals("SELECT")&&!t.options.isEmpty()){int i=index(value,t.options.size());if(t.kind.equals("switches")){p.input=value;@SuppressWarnings("unchecked") var hints=new ArrayList<>((List<String>)t.display.get("tileHints"));@SuppressWarnings("unchecked") var lamps=new ArrayList<>((List<Boolean>)t.display.get("lamps"));boolean on=!hints.get(i).equals("SET");hints.set(i,on?"SET":"RESET");lamps.set(i,on);if(i==t.target){if(t.low==0){hints.set(i,on?"RESET":"SET");lamps.set(i,!on);}else if(t.low==1)lamps.set(i,false);else if(t.low==2){lamps.set(i,false);lamps.set((i+1)%4,on);}else lamps.set(i,!on);}t.display.put("tileHints",hints);t.display.put("lamps",lamps);}
                else if(t.kind.equals("sequence")){correct=value.equals(t.steps.get(p.sequence));if(correct){p.sequence++;submit=p.sequence==t.steps.size();}else submit=true;}
                else{submit=true;correct=t.answer.startsWith("except:")?!value.equals(t.answer.substring(7)):t.answer.equals(value);}}
            else if(action.equals("CONFIRM")){submit=true;correct=switch(t.kind){case "number"->p.input.equals(t.answer);case "circuit"->connected(t.cells);case "pressure"->t.pressure>=t.low&&t.pressure<=t.high;case "radio"->Math.abs(t.frequency-t.target/10.0)<=.30001;case "balance"->t.pressure==t.target;case "switches"->p.input.equals(t.answer);case "timing"->{double position=timingPosition(t,now-p.rtt/2-p.readyAt);yield position>=t.low&&position<=t.high;}case "silence"->now-p.rtt/2>=p.readyAt+t.target;case "delayed"->now-p.rtt/2>=p.readyAt+2000&&now-p.rtt/2<p.readyAt+3000;default->false;};}else return false;
        }else{
            var required=mechanisms(p);if(!required.contains(element))return false;if(action.equals("RELEASE"))return false;
            String key=switch(element){case "LEVER_MODULE"->"lever";case "ADJUSTER"->"adjuster";case "LIGHT_MODULE"->"light";case "HIDDEN_HATCH"->"hatch";case "CODE_PANEL"->"code";case "ANIMAL_PANEL"->"animal";case "SYMBOL_PANEL"->"symbol";default->"";};
            if(element.equals("LEVER_MODULE")&&action.equals("SET")&&List.of("UP","MIDDLE","DOWN").contains(value))p.mechanisms.put(key,value);
            else if(element.equals("ADJUSTER")&&action.equals("SET")&&Set.of("0","45","90","135").contains(value)){int next=Integer.parseInt(value),previous=(int)p.mechanisms.get("adjuster");p.mechanisms.put(key,next);int delta=Math.floorMod(next-previous,180)==135?-1:1;if(t.kind.equals("pressure")){t.pressure=Math.max(0,Math.min(100,t.pressure+delta*5));t.velocity=delta*2;}else if(t.kind.equals("radio"))t.frequency=Math.max(88,Math.min(108,t.frequency+delta*.5));else if(t.kind.equals("balance"))t.pressure=Math.max(0,Math.min(100,t.pressure+delta));}
            else if(element.equals("LIGHT_MODULE")&&action.equals("SET")&&COLORS.contains(value))p.mechanisms.put(key,value);
            else if(element.equals("HIDDEN_HATCH")&&action.equals("SET")&&Set.of("OPEN","CLOSED").contains(value)){p.mechanisms.put(key,value.equals("OPEN"));if(p.family.equals("HATCH")&&value.equals("OPEN"))p.foundNote=true;}
            else if(element.equals("CODE_PANEL")&&action.equals("STEP")&&value.matches("[0-3]:[+-]1")){char[] code=p.mechanisms.get("code").toString().toCharArray();int i=value.charAt(0)-'0';code[i]=(char)('0'+Math.floorMod(code[i]-'0'+(value.charAt(2)=='+'?1:-1),10));p.mechanisms.put(key,new String(code));}
            else if(element.equals("ANIMAL_PANEL")&&action.equals("SELECT")&&ANIMALS.contains(value))p.mechanisms.put(key,value);
            else if(element.equals("SYMBOL_PANEL")&&action.equals("SELECT")&&List.of("SUN","MOON","STAR","KEY").contains(value))p.mechanisms.put(key,value);
            else if(!(element.equals("BIG_BUTTON")&&action.equals("PRESS")))return false;
            if(t.kind.equals("sequence")){String step=element+":"+(element.equals("BIG_BUTTON")?"PRESS":value);correct=t.steps.get(p.sequence).equals(step);if(correct){p.sequence++;submit=p.sequence==t.steps.size();}else submit=true;}
            else if(element.equals("BIG_BUTTON")&&Set.of("pressure","radio","balance").contains(t.kind)){submit=true;correct=t.kind.equals("pressure")?t.pressure>=t.low&&t.pressure<=t.high:t.kind.equals("radio")?Math.abs(t.frequency-t.target/10.)<=.30001:t.pressure==t.target;}
            else if(element.equals("BIG_BUTTON")){submit=true;correct=(!p.family.equals("HATCH")||p.foundNote)&&t.answer.equals(String.valueOf(p.mechanisms.get(switch(p.family){case "LEVER"->"lever";case "ADJUSTER"->"adjuster";case "COLOR"->"light";case "ANIMAL"->"animal";case "SYMBOL"->"symbol";default->"code";})));}

        }
        if(submit){p.feedback=correct?"COMMAND ACCEPTED":"WRONG COMMAND";if(!correct)p.failures++;if(correct){telemetry.put(p.family,telemetry.getOrDefault(p.family,new Telemetry(0,0)).add(Math.max(0,now-p.readyAt-p.rtt/2)));p.score++;if(p.family.equals("RECALL"))p.memory=null;if(p.score==20){winner=id;finishedAt=now;}}p.nextAt=now+250;}
        return true;
    }
    static double timingPosition(Task task,long elapsed){double period=((Number)task.display.get("period")).doubleValue(),direction=((Number)task.display.get("direction")).doubleValue(),start=((Number)task.display.get("start")).doubleValue();double position=(start+elapsed/period*100*direction)%100;return position<0?position+100:position;}
    static int index(String value,int size){try{int i=Integer.parseInt(value);if(i>=0&&i<size)return i;}catch(NumberFormatException ignored){}throw new RoomService.Failure(400,"INVALID_COMMAND_INDEX");}
    List<String> mechanisms(Player p){if(p.family.equals("NUMBER_MEMORY")&&p.memory!=null&&p.memory.kind.equals("LIGHT_SEQUENCE"))return List.of("LIGHT_MODULE","SIGNAL_PANEL");if(p.family.equals("RECALL")&&p.task!=null&&p.task.kind.equals("sequence"))return List.of("SMALL_BUTTON_1","SMALL_BUTTON_2","SMALL_BUTTON_3","SMALL_BUTTON_4");return switch(p.family){case "TIMING","SILENCE","DELAYED_EXECUTION"->List.of("BIG_BUTTON");case "BUTTON","FORBIDDEN","CONDITIONAL","STROOP","FALSE_COMMAND"->List.of("SMALL_BUTTON_1","SMALL_BUTTON_2","SMALL_BUTTON_3","SMALL_BUTTON_4");case "LIGHT_MEMORY"->List.of("LIGHT_MODULE","SIGNAL_PANEL","SMALL_BUTTON_1","SMALL_BUTTON_2","SMALL_BUTTON_3","SMALL_BUTTON_4");case "PRESSURE","RADIO","BALANCE"->List.of("ADJUSTER","BIG_BUTTON");case "LEVER_SEQUENCE","SHUTDOWN"->List.of("LEVER_MODULE","ADJUSTER","BIG_BUTTON");case "LEVER"->List.of("LEVER_MODULE","BIG_BUTTON");case "ADJUSTER"->List.of("ADJUSTER","BIG_BUTTON");case "COLOR"->List.of("LIGHT_MODULE","BIG_BUTTON");case "ANIMAL"->List.of("ANIMAL_PANEL","BIG_BUTTON");case "SYMBOL"->List.of("SYMBOL_PANEL","BIG_BUTTON");case "ENTER_CODE"->List.of("CODE_PANEL","BIG_BUTTON");case "HATCH"->List.of("HIDDEN_HATCH","CODE_PANEL","BIG_BUTTON");default->List.of();};}
    String taskId(Player p){return p.instanceId;}
    boolean tick(long now){if(!started||!winner.isEmpty())return false;boolean changed=false;for(var e:players.entrySet()){Player p=e.getValue();if(!p.online)continue;if(p.task!=null&&p.task.kind.equals("pressure")&&Math.abs(p.task.velocity)>.03){Task t=p.task;double elapsed=Math.max(0,Math.min(.25,(now-t.lastTime)/1000.));t.pressure=Math.max(0,Math.min(100,t.pressure+t.velocity*elapsed));t.velocity*=Math.exp(-3*elapsed);changed=true;}if(p.task!=null)p.task.lastTime=now;if(p.revealUntil>0&&now>=p.revealUntil&&!p.revealed){p.revealed=true;changed=true;}if(p.nextAt>0&&now>=p.nextAt||p.task!=null&&p.task.kind.equals("store")&&now>=p.revealUntil){next(e.getKey(),p,now);changed=true;}}return changed;}
    Map<String,Object> snapshot(String id,long now){Player p=player(id,now);if(!p.hidden)resume(p,now);if(p.clockSent<0)p.clockSent=now;Map<String,Object> out=new LinkedHashMap<>(p.mechanisms);out.put("clockChallenge",p.clockConfirmed?"":p.clockNonce);out.put("clockRttMs",p.rtt);out.put("held",List.of());out.put("locked",List.of());out.put("sequence",p.serial*100L+p.sequence+p.requests.size());out.put("lastAction",Map.of());if(p.family.equals("HATCH")&&p.task!=null&&Boolean.TRUE.equals(p.mechanisms.get("hatch"))&&(!requireReady||barrierOpen))out.put("hint",p.task.answer);Map<String,Object> r=new LinkedHashMap<>();r.put("waitingForTerminals",requireReady&&!barrierOpen);r.put("awaitingReady",!p.ready);r.put("paused",!p.online);r.put("previewFamily",p.previewFamily);r.put("campaign",true);r.put("expanded",true);r.put("scenario","campaign");r.put("status",!winner.isEmpty()?"WON":started?"PLAYING":"READY");r.put("step",p.score);r.put("localScore",p.score);r.put("steps",20);r.put("mistakes",p.failures);r.put("scores",scores());r.put("winner",winner);r.put("finishedAt",finishedAt);r.put("readyAt",p.readyAt);r.put("nextAt",p.nextAt);r.put("feedback",p.feedback);r.put("attemptId",Long.toString(startedAt));r.put("round",0);r.put("elapsedMs",(finishedAt>0?finishedAt:now)-raceTime);r.put("finishReason",winner.isEmpty()?"":"COMPLETED");r.put("replays",0);r.put("deadline",0);r.put("signals",p.task!=null&&p.task.display.containsKey("flashes")&&now<p.revealUntil?((List<?>)p.task.display.get("flashes")).stream().map(x->"SMALL_BUTTON_"+(Integer.parseInt(x.toString())+1)).toList():List.of());r.put("signalStartedAt",p.readyAt);r.put("inputAt",p.revealUntil);r.put("taskId",taskId(p));r.put("taskType",p.family);r.put("estimatedCompletionMs",p.task==null?0:p.task.estimatedMillis);r.put("category",p.category);r.put("difficulty",difficulty);r.put("requiredMechanisms",p.task==null||p.nextAt>0?List.of():mechanisms(p));r.put("focusId",p.task==null||mechanisms(p).isEmpty()?"SCREEN":mechanisms(p).get(0));
        String instruction=!started?"THE LAST COMMAND / PRESS START":!winner.isEmpty()?"PROTOCOL COMPLETE":p.nextAt>0?p.feedback:p.task.instruction;
        if(p.revealUntil>0&&now>=p.revealUntil&&Set.of("REVERSE","SHUTDOWN","LIGHT_MEMORY","SYMBOL_MEMORY","ANIMAL_MEMORY","FIND_CHANGE").contains(p.family))instruction=p.task.display.containsKey("afterInstruction")?p.task.display.get("afterInstruction").toString():"REPRODUCE "+(p.family.equals("REVERSE")?"IN REVERSE ORDER":"THE STORED SEQUENCE");
        boolean waiting=requireReady&&!barrierOpen;if(waiting){instruction="WAITING FOR TERMINALS";r.put("taskType","");r.put("category","");r.put("requiredMechanisms",List.of());r.put("signals",List.of());r.put("inputAt",0);r.put("signalStartedAt",0);r.put("focusId","SCREEN");}r.put("instruction",CommandText.ru(instruction));if(waiting)r.put("touchscreen",Map.of("kind","waiting","options",List.of(),"revealUntil",0));if(p.task!=null&&!waiting){Task t=p.task;Map<String,Object> screen=new LinkedHashMap<>(t.display);for(String key:List.of("afterInstruction","spoken"))if(screen.containsKey(key))screen.put(key,CommandText.ru(screen.get(key).toString()));if(now>=p.revealUntil){screen.remove("flashes");screen.remove("original");}screen.put("adjusterAngle",p.mechanisms.get("adjuster"));screen.put("canRestartMemory",Set.of("NUMBER_MEMORY","RECALL").contains(p.family));screen.put("kind",t.kind);screen.put("options",p.family.equals("FIND_CHANGE")&&now<p.revealUntil?t.display.get("original"):t.options);screen.put("input",p.input);screen.put("sequencePosition",p.sequence);screen.put("revealUntil",p.revealUntil);screen.put("value",t.kind.equals("radio")?t.frequency:t.pressure);screen.put("serverTime",now);if(t.kind.equals("radio"))screen.put("strength",Math.max(0,1-Math.abs(t.frequency-t.target/10.0)/3));if(t.cells!=null)screen.put("board",Arrays.stream(t.cells).boxed().toList());r.put("touchscreen",screen);}out.put("testRound",r);return out;}
    Map<String,Integer> scores(){Map<String,Integer> result=new LinkedHashMap<>();players.forEach((id,p)->result.put(id,p.score));return result;}
}
